insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/regions/imereti', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"Kutaisi was the capital until the Middle Ages." Gelati is a UNESCO World Heritage monument. Bagrati Cathedral, built in 1003, is "a symbol of the country''s unity". Prometheus Cave and Sataplia are listed among the "natural wonders worth seeing in Imereti".')
