-- Keep one row per (publisher, url): re-running must not accumulate copies.
delete from public.expat_citations a
using public.expat_citations b
where a.publisher = b.publisher
  and a.url is not distinct from b.url
  and a.ctid > b.ctid
  and not exists (select 1 from public.expat_fact_citations fc where fc.citation_id = a.id)
  and not exists (select 1 from public.expat_cost_observations co where co.citation_id = a.id)
  and not exists (select 1 from public.expat_places p where p.citation_id = a.id);

-- cities-and-neighbourhoods
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('cities-and-neighbourhoods', 'GE', 'DAILY_LIFE', 'LIVE', '{"en":{"title":"Cities and neighbourhoods","summary":"Most newcomers settle in Tbilisi or Batumi, and some choose Kutaisi. Each Tbilisi district has its own feel, so walk around a few before you decide.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"Tbilisi is the capital and the biggest city, with the most work, schools and services. Batumi is the seaside city on the Black Sea. Kutaisi in the west is calmer and smaller. Inside Tbilisi, the old centre is lively and close to everything, Vake and Vera are greener and quieter, and Saburtalo is practical for everyday life with the metro close by."},{"kind":"WHERE","heading":"Tbilisi, district by district","body":"Old Tbilisi and Sololaki: the historic heart, hilly and cobbled, with the sulphur baths and everything within walking distance. Expect visitors and some noise. Mtatsminda and Rustaveli Avenue: central, with the hill and its park above the city. Vera and Vake: quieter and greener, and Vake is seen as one of the most prestigious places to live. Saburtalo: good for longer stays, with the metro, shops and moderate prices. Didube: a bit cheaper, with good metro links. Marjanishvili, around Fabrika: lively and full of bars. Didi Dighomi and Gldani: large residential districts further from the centre, with lots of apartment blocks and a more local, everyday feel."},{"kind":"WHERE","heading":"Batumi","body":"Batumi sits on the Black Sea coast and is the main city of Adjara. Life here is built around the sea and the long Boulevard by the beach. It is busy in summer and much quieter in the cold months, so if you can, visit in both seasons before you sign a long lease."},{"kind":"WHERE","heading":"Kutaisi, Zugdidi and other cities","body":"Kutaisi was the capital of old Imereti and is now a calm city with Bagrati Cathedral and Gelati Monastery close by, and its own airport. Zugdidi is the main city of Samegrelo, home to the Dadiani Palace museum and the usual road to Svaneti. Other towns people move to include Rustavi near Tbilisi, Telavi in the Kakheti wine country, and seaside towns along the coast such as Kobuleti."},{"kind":"PRACTICAL","heading":"How to choose","body":"Visit a street in the morning and again at night. Check how far the nearest metro or bus stop is, how steep the hill is, and how the flat is heated in winter. Ask neighbours what it is like. For what things cost, see our cost of living page, because we keep prices there and update them."}]},"ka":{"title":"ქალაქები და უბნები","summary":"ახალჩამოსულთა უმეტესობა თბილისში ან ბათუმში სახლდება, ზოგი ქუთაისს ირჩევს. თბილისში ყველა უბანს თავისი ხასიათი აქვს, ამიტომ არჩევამდე რამდენიმე მათგანი მოიარეთ.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"თბილისი დედაქალაქი და ყველაზე დიდი ქალაქია, აქ არის ყველაზე მეტი სამსახური, სკოლა და მომსახურება. ბათუმი შავი ზღვის სანაპიროს ქალაქია. ქუთაისი დასავლეთში უფრო მშვიდი და პატარაა. თბილისში ძველი ცენტრი ცოცხალია და ყველაფერთან ახლოს, ვაკე და ვერა უფრო მწვანე და წყნარია, საბურთალო კი ყოველდღიური ცხოვრებისთვის მოსახერხებელია და მეტრო ახლოსაა."},{"kind":"WHERE","heading":"თბილისი, უბან უბან","body":"ძველი თბილისი და სოლოლაკი: ისტორიული გული, აღმართები და ქვაფენილი, აბანოები და ყველაფერი ფეხით სავალ მანძილზე. აქ ბევრი სტუმარია და ხანდახან ხმაურია. მთაწმინდა და რუსთაველის გამზირი: ცენტრი, ქალაქს ზემოთ მთა და მისი პარკი. ვერა და ვაკე: უფრო წყნარი და მწვანე, ვაკე კი ერთ-ერთ ყველაზე პრესტიჟულ საცხოვრებელ უბნად ითვლება. საბურთალო: კარგია ხანგრძლივად ცხოვრებისთვის, მეტროთი, მაღაზიებით და ზომიერი ფასებით. დიდუბე: ცოტა უფრო იაფი, კარგი მეტრო კავშირით. მარჯანიშვილი, ფაბრიკის მიდამოები: ცოცხალი, ბევრი ბარით. დიდი დიღომი და გლდანი: ცენტრიდან მოშორებული დიდი საცხოვრებელი უბნები, ბევრი მრავალბინიანი სახლით და უფრო ადგილობრივი, ყოველდღიური ცხოვრებით."},{"kind":"WHERE","heading":"ბათუმი","body":"ბათუმი შავი ზღვის სანაპიროზეა და აჭარის მთავარი ქალაქია. აქ ცხოვრება ზღვისა და სანაპიროს გრძელი ბულვარის გარშემო ტრიალებს. ზაფხულში ხალხმრავალია, ცივ თვეებში კი გაცილებით წყნარი, ამიტომ, თუ შეძლებთ, გრძელვადიან ქირაობამდე ორივე სეზონში ნახეთ."},{"kind":"WHERE","heading":"ქუთაისი, ზუგდიდი და სხვა ქალაქები","body":"ქუთაისი ძველი იმერეთის დედაქალაქი იყო, დღეს კი მშვიდი ქალაქია, ახლოს ბაგრატის ტაძრით და გელათის მონასტრით, საკუთარი აეროპორტით. ზუგდიდი სამეგრელოს მთავარი ქალაქია, აქ არის დადიანების სასახლის მუზეუმი და აქედან მიდის ჩვეული გზა სვანეთისკენ. ხალხი ასევე სახლდება რუსთავში თბილისთან ახლოს, თელავში კახეთის ღვინის მხარეში და ზღვისპირა ქალაქებში, მაგალითად ქობულეთში."},{"kind":"PRACTICAL","heading":"როგორ აირჩიოთ","body":"ქუჩა ნახეთ დილით და ერთხელ ღამითაც. გადაამოწმეთ, რამდენად შორსაა მეტრო ან გაჩერება, რამდენად ციცაბოა აღმართი და როგორ თბება ბინა ზამთარში. ჰკითხეთ მეზობლებს, როგორია აქ ცხოვრება. ფასებისთვის ნახეთ ჩვენი გვერდი ცხოვრების ღირებულებაზე, იქ ვინახავთ და ვაახლებთ ფასებს."}]},"ru":{"title":"Города и районы","summary":"Большинство приезжих живёт в Тбилиси или Батуми, некоторые выбирают Кутаиси. У каждого района Тбилиси свой характер, так что прогуляйтесь по нескольким, прежде чем решать.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Тбилиси это столица и самый большой город, здесь больше всего работы, школ и услуг. Батуми это город у Чёрного моря. Кутаиси на западе спокойнее и меньше. В Тбилиси старый центр оживлённый и близко ко всему, Ваке и Вера зеленее и тише, а Сабуртало удобно для повседневной жизни, и метро рядом."},{"kind":"WHERE","heading":"Тбилиси по районам","body":"Старый Тбилиси и Сололаки: историческое сердце, холмы и брусчатка, серные бани, всё в пешей доступности. Здесь много гостей и бывает шумно. Мтацминда и проспект Руставели: центр, над городом гора и её парк. Вера и Ваке: тише и зеленее, а Ваке считается одним из самых престижных районов для жизни. Сабуртало: хорошо для долгого проживания, есть метро, магазины и умеренные цены. Дидубе: чуть дешевле, с хорошим метро. Марджанишвили, около Фабрики: оживлённо, много баров. Диди Дигоми и Глдани: большие спальные районы дальше от центра, много многоэтажек и более местная, будничная жизнь."},{"kind":"WHERE","heading":"Батуми","body":"Батуми стоит на берегу Чёрного моря и это главный город Аджарии. Жизнь здесь крутится вокруг моря и длинного Бульвара вдоль пляжа. Летом многолюдно, в холодные месяцы гораздо тише, поэтому, если можете, посмотрите город в оба сезона, прежде чем подписывать долгую аренду."},{"kind":"WHERE","heading":"Кутаиси, Зугдиди и другие города","body":"Кутаиси был столицей древней Имеретии, а сейчас это спокойный город, рядом храм Баграта и монастырь Гелати, есть свой аэропорт. Зугдиди это главный город Самегрело, здесь музей во дворце Дадиани и обычная дорога в Сванетию. Ещё переезжают в Рустави рядом с Тбилиси, в Телави в винной Кахетии и в приморские города, например Кобулети."},{"kind":"PRACTICAL","heading":"Как выбрать","body":"Посмотрите улицу утром и ещё раз вечером. Проверьте, далеко ли метро или остановка, насколько крутой подъём и как квартира отапливается зимой. Спросите соседей, как тут живётся. Цены смотрите на нашей странице о стоимости жизни, мы держим их там и обновляем."}]},"tr":{"title":"Şehirler ve semtler","summary":"Yeni gelenlerin çoğu Tiflis ya da Batum''a yerleşir, bazıları Kutaisi''yi seçer. Tiflis''in her semtinin kendine özgü bir havası var, karar vermeden önce birkaçını gezin.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Tiflis başkent ve en büyük şehirdir, en çok iş, okul ve hizmet buradadır. Batum Karadeniz kıyısındaki şehirdir. Batıdaki Kutaisi daha sakin ve küçüktür. Tiflis''te eski merkez canlı ve her yere yakındır, Vake ve Vera daha yeşil ve sakindir, Saburtalo ise metroya yakınlığıyla günlük hayat için pratiktir."},{"kind":"WHERE","heading":"Tiflis, semt semt","body":"Eski Tiflis ve Sololaki: tarihi kalp, yokuşlu ve parke taşlı, kükürt hamamları ve her şey yürüme mesafesinde. Ziyaretçi çoktur, biraz gürültü olabilir. Mtatsminda ve Rustaveli Caddesi: merkez, şehrin üstünde tepe ve parkı. Vera ve Vake: daha sakin ve yeşil, Vake en prestijli oturma semtlerinden biri sayılır. Saburtalo: uzun kalış için iyi, metro, mağazalar ve makul fiyatlar. Didube: biraz daha ucuz, metro bağlantısı iyi. Marjanishvili, Fabrika çevresi: canlı, bol barlı. Didi Dighomi ve Gldani: merkezden uzak büyük konut semtleri, çok sayıda apartman ve daha yerel, gündelik bir hayat."},{"kind":"WHERE","heading":"Batum","body":"Batum Karadeniz kıyısında, Acara''nın ana şehridir. Hayat deniz ve plaj boyunca uzanan Bulvar etrafında döner. Yazın kalabalık, soğuk aylarda çok daha sakindir. Mümkünse uzun bir kira sözleşmesi imzalamadan önce iki mevsimde de görün."},{"kind":"WHERE","heading":"Kutaisi, Zugdidi ve diğer şehirler","body":"Kutaisi eski İmereti''nin başkentiydi, bugün Bagrati Katedrali ve Gelati Manastırı''na yakın, kendi havalimanı olan sakin bir şehir. Zugdidi Samegrelo''nun ana şehri, Dadiani Sarayı müzesi burada ve Svaneti''ye giden yol genelde buradan geçer. İnsanlar ayrıca Tiflis yakınındaki Rustavi''ye, Kaheti şarap bölgesindeki Telavi''ye ve Kobuleti gibi sahil kasabalarına taşınır."},{"kind":"PRACTICAL","heading":"Nasıl seçilir","body":"Sokağa sabah bir kez, akşam bir kez bakın. En yakın metro ya da durağın ne kadar uzak olduğunu, yokuşun ne kadar dik olduğunu ve dairenin kışın nasıl ısındığını kontrol edin. Komşulara sorun. Fiyatlar için yaşam maliyeti sayfamıza bakın, fiyatları orada tutup güncelliyoruz."}]},"ar":{"title":"المدن والأحياء","summary":"معظم القادمين الجدد يستقرون في تبليسي أو باتومي، وبعضهم يختار كوتايسي. ولكل حي في تبليسي طابعه، فتجوّل في عدة أحياء قبل أن تقرر.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"تبليسي هي العاصمة وأكبر مدينة، وفيها أكثر فرص العمل والمدارس والخدمات. باتومي مدينة ساحلية على البحر الأسود. وكوتايسي في الغرب أهدأ وأصغر. داخل تبليسي، المركز القديم حيوي وقريب من كل شيء، وفاكي وفيرا أكثر خضرة وهدوءًا، وسابورتالو عملي للحياة اليومية والمترو قريب منه."},{"kind":"WHERE","heading":"تبليسي حيًّا حيًّا","body":"تبليسي القديمة وسولولاكي: القلب التاريخي، تلال وشوارع مرصوفة بالحجر، وحمامات الكبريت، وكل شيء على مسافة مشي. توقّع زوارًا كثيرين وبعض الضجيج. متاتسميندا وشارع روستافيلي: وسط المدينة، وفوقها الجبل وحديقته. فيرا وفاكي: أهدأ وأكثر خضرة، وفاكي يُعد من أرقى أحياء السكن. سابورتالو: مناسب للإقامة الطويلة، فيه مترو ومحلات وأسعار معتدلة. ديدوبي: أرخص قليلًا ومتصل جيدًا بالمترو. مارجانيشفيلي حول فابريكا: حيوي ومليء بالمقاهي والبارات. ديدي ديغومي وغلداني: أحياء سكنية كبيرة بعيدة عن المركز، فيها عمارات كثيرة وحياة يومية محلية أكثر."},{"kind":"WHERE","heading":"باتومي","body":"تقع باتومي على ساحل البحر الأسود، وهي المدينة الرئيسية في أجاريا. الحياة فيها تدور حول البحر والكورنيش الطويل بجانب الشاطئ. مزدحمة في الصيف وأهدأ بكثير في الأشهر الباردة، فإن استطعت زُرها في الموسمين قبل أن توقّع عقد إيجار طويل."},{"kind":"WHERE","heading":"كوتايسي وزوغديدي ومدن أخرى","body":"كانت كوتايسي عاصمة إيميريتي قديمًا، وهي اليوم مدينة هادئة قريبة من كاتدرائية باغراتي ودير غيلاتي، ولها مطارها. زوغديدي هي المدينة الرئيسية في ساميغريلو، وفيها متحف قصر دادياني، ومنها يمر الطريق المعتاد إلى سفانيتي. ويسكن الناس أيضًا في روستافي قرب تبليسي، وفي تيلافي في منطقة النبيذ كاخيتي، وفي مدن ساحلية مثل كوبوليتي."},{"kind":"PRACTICAL","heading":"كيف تختار","body":"زُر الشارع صباحًا ثم مرة أخرى ليلًا. انظر كم تبعد أقرب محطة مترو أو حافلة، وكم الطلعة شديدة، وكيف تُدفأ الشقة في الشتاء. واسأل الجيران عن الحياة هناك. أما الأسعار فتجدها في صفحتنا عن تكاليف المعيشة، حيث نحفظها ونحدّثها."}]},"he":{"title":"ערים ושכונות","summary":"רוב מי שמגיעים מתיישבים בטביליסי או בבטומי, וחלק בוחרים בקוטאיסי. לכל שכונה בטביליסי יש אופי משלה, אז הסתובבו בכמה לפני שמחליטים.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"טביליסי היא הבירה והעיר הגדולה ביותר, ויש בה הכי הרבה עבודה, בתי ספר ושירותים. בטומי היא עיר החוף על הים השחור. קוטאיסי במערב שקטה וקטנה יותר. בתוך טביליסי, המרכז הישן תוסס וקרוב להכול, ואקה ו־ורה ירוקות ושקטות יותר, וסבורטלו נוחה לחיי היומיום עם מטרו קרוב."},{"kind":"WHERE","heading":"טביליסי, שכונה אחרי שכונה","body":"טביליסי העתיקה וסולולאקי: הלב ההיסטורי, גבעות ורחובות אבן, מרחצאות הגופרית והכול במרחק הליכה. יש הרבה מבקרים ולפעמים רעש. מטצמינדה ושדרות רוסטאוולי: מרכז העיר, ומעליה ההר והפארק שלו. ורה ו־ואקה: שקטות וירוקות יותר, וואקה נחשבת לאחת משכונות המגורים היוקרתיות. סבורטלו: טובה לשהייה ארוכה, עם מטרו, חנויות ומחירים סבירים. דידובה: קצת זולה יותר, עם חיבור טוב למטרו. מרג׳נישווילי, סביב פבריקה: תוססת ומלאה בברים. דידי דיגומי וגלדאני: שכונות מגורים גדולות רחוק יותר מהמרכז, עם הרבה בנייני דירות ואווירה מקומית ויומיומית."},{"kind":"WHERE","heading":"בטומי","body":"בטומי שוכנת על חוף הים השחור והיא העיר הראשית של אג׳ריה. החיים בה סובבים סביב הים והטיילת הארוכה לאורך החוף. בקיץ היא עמוסה, ובחודשים הקרים הרבה יותר שקטה, אז אם אפשר, בקרו בשתי העונות לפני שחותמים על שכירות ארוכה."},{"kind":"WHERE","heading":"קוטאיסי, זוגדידי וערים אחרות","body":"קוטאיסי הייתה בירת אימרתי בעבר, והיום היא עיר שקטה עם קתדרלת בגרטי ומנזר גלאטי בסביבה, ושדה תעופה משלה. זוגדידי היא העיר הראשית של סמגרלו, יש בה מוזיאון ארמון דדיאני, ודרכה עובר בדרך כלל הכביש לסוואנטי. אנשים עוברים גם לרוסטאווי ליד טביליסי, לתלאווי באזור היין קאחתי ולעיירות חוף כמו קובולטי."},{"kind":"PRACTICAL","heading":"איך בוחרים","body":"בקרו ברחוב בבוקר ושוב בלילה. בדקו כמה רחוקה תחנת המטרו או האוטובוס, כמה תלולה העלייה ואיך הדירה מחוממת בחורף. שאלו שכנים איך החיים שם. את המחירים תמצאו בעמוד שלנו על יוקר המחיה, שם אנחנו שומרים ומעדכנים אותם."}]}}'::jsonb,
        'GENERAL', 'PRACTICAL_CONTEXT', 70,
        true, false, null,
        now(), now() + interval '90 days')
