insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'tbilisi-district-character', 'GENERAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"In Tbilisi, the Old Town is hilly and close to everything, Vera and Vake are quieter and greener, Vake is considered one of the most prestigious residential districts, and Saburtalo suits longer stays with the metro, shops and moderate prices.","ka":"თბილისში ძველი ქალაქი აღმართიანია და ყველაფერთან ახლოსაა, ვერა და ვაკე უფრო წყნარი და მწვანეა, ვაკე ერთ-ერთ ყველაზე პრესტიჟულ საცხოვრებელ უბნად ითვლება, საბურთალო კი ხანგრძლივი ცხოვრებისთვის ვარგა მეტროთი, მაღაზიებით და ზომიერი ფასებით.","ru":"В Тбилиси Старый город холмистый и близко ко всему, Вера и Ваке тише и зеленее, Ваке считается одним из самых престижных жилых районов, а Сабуртало подходит для долгого проживания: метро, магазины и умеренные цены.","tr":"Tiflis''te Eski Şehir yokuşludur ve her yere yakındır, Vera ve Vake daha sakin ve yeşildir, Vake en prestijli konut semtlerinden biri sayılır, Saburtalo ise metro, mağazalar ve makul fiyatlarla uzun kalışa uygundur.","ar":"في تبليسي، المدينة القديمة تلّية وقريبة من كل شيء، وفيرا وفاكي أهدأ وأكثر خضرة، وفاكي يُعد من أرقى الأحياء السكنية، وسابورتالو يناسب الإقامة الطويلة بفضل المترو والمحلات والأسعار المعتدلة.","he":"בטביליסי, העיר העתיקה הררית וקרובה להכול, ורה ו־ואקה שקטות וירוקות יותר, ואקה נחשבת לאחת משכונות המגורים היוקרתיות, וסבורטלו מתאימה לשהייה ארוכה עם מטרו, חנויות ומחירים סבירים."}'::jsonb, null, null,
       false
