insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'cities-and-neighbourhoods'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Madloba.info' and url is not distinct from 'https://madloba.info/en/faq/housing/where-to-stay-in-tbilisi/'
  order by created_at limit 1) c
where f.fact_key = 'tbilisi-district-character'
on conflict do nothing;
