insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('renting-a-home', 'GE', 'PROPERTY', 'LIVE', '{"en":{"title":"Renting a home","summary":"Renting in Georgia is mostly a matter of agreement between you and the owner. That makes it fast, and it also means the protection you get is what you write down.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"Find a place, see it in person, check that the person renting it to you really owns it, and sign a written lease. You usually pay the first month and a deposit when you sign. The law does not require a written lease for a household rental, but without one you have very little to show if something goes wrong, so always have one."},{"kind":"WHAT_YOU_NEED","heading":"What to have ready","body":"Your passport, the first month''s rent and a deposit. A deposit of one or two months is common practice for long rentals. It is a custom, not a fixed amount in law, so agree in the lease how much it is, when you get it back and what can be taken from it. If an agent shows you the flat, ask before the viewing whether you pay them anything."},{"kind":"PRACTICAL","heading":"Check who owns the flat","body":"The Public Registry (NAPR) keeps the real estate register, and an extract from it shows who owns a property and whether there are restrictions, mortgages or leases on it. You can request one on napr.gov.ge or at a Public Service Hall. Compare the owner''s name with the passport of the person signing. If someone else signs for the owner, ask to see their power of attorney."},{"kind":"PRACTICAL","heading":"Bills and utilities","body":"For flats, electricity, gas, water and internet are usually paid separately by the tenant. Agree in writing who pays what. On the day you move in, take photos of every meter, and of the flat and furniture, and keep them."},{"kind":"NOTES","heading":"Notary and registering the lease","body":"Most leases are simply signed by both sides. A notarised lease is needed only in some cases, for example when you use it for a residence permit or to register your place of residence. The Public Registry also keeps a register of leases if you want yours recorded. Ask at a Public Service Hall what that involves for your case. Get the lease in a language you understand, or side by side with a translation."},{"kind":"PROBLEMS","heading":"What usually goes wrong","body":"The deposit is not returned, because nobody wrote down what state the flat was in. A bill from before you arrived turns up in your name. The person who signed was not the owner. Do not sign on the first visit, pay by bank transfer with a note, and keep every photo and receipt."}]},"ka":{"title":"ბინის ქირაობა","summary":"საქართველოში ქირაობა ძირითადად თქვენსა და მესაკუთრეს შორის შეთანხმებაა. ეს საქმეს აჩქარებს, თუმცა ნიშნავს იმასაც, რომ თქვენი დაცვა ის არის, რასაც ქაღალდზე ჩაწერთ.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"იპოვეთ ბინა, ნახეთ ის პირადად, გადაამოწმეთ, რომ ვინც გაქირავებთ, ნამდვილად მესაკუთრეა, და გააფორმეთ წერილობითი ხელშეკრულება. ხელმოწერისას, როგორც წესი, პირველი თვის ქირას და დეპოზიტს იხდით. საყოფაცხოვრებო ქირაობისთვის კანონი წერილობით ხელშეკრულებას არ ითხოვს, მაგრამ მის გარეშე პრობლემის დროს თითქმის ვერაფერს დაამტკიცებთ, ამიტომ ყოველთვის გააფორმეთ."},{"kind":"WHAT_YOU_NEED","heading":"რა უნდა გქონდეთ","body":"პასპორტი, პირველი თვის ქირა და დეპოზიტი. გრძელვადიან ქირაობაზე ერთი ან ორი თვის დეპოზიტი გავრცელებული პრაქტიკაა. ეს ჩვეულებაა და არა კანონით დადგენილი თანხა, ამიტომ ხელშეკრულებაში შეთანხმდით, რამდენია, როდის დაგიბრუნდებათ და რა შეიძლება დაიქვითოს. თუ ბინას აგენტი გაჩვენებთ, ნახვამდე ჰკითხეთ, გიწევთ თუ არა მისთვის გადახდა."},{"kind":"PRACTICAL","heading":"გადაამოწმეთ, ვისია ბინა","body":"საჯარო რეესტრის ეროვნული სააგენტო უძრავი ქონების რეესტრს აწარმოებს, და ამონაწერი აჩვენებს, ვისია ქონება და აქვს თუ არა შეზღუდვა, იპოთეკა ან იჯარა. მოითხოვეთ napr.gov.ge-ზე ან იუსტიციის სახლში. შეადარეთ მესაკუთრის სახელი ხელმომწერის პასპორტს. თუ მესაკუთრის ნაცვლად სხვა აწერს ხელს, სთხოვეთ მინდობილობა."},{"kind":"PRACTICAL","heading":"კომუნალური გადასახადები","body":"ბინაში დენს, გაზს, წყალს და ინტერნეტს, როგორც წესი, მოიჯარე ცალკე იხდის. წერილობით შეთანხმდით, ვინ რას იხდის. შესვლის დღეს გადაუღეთ ფოტო ყველა მრიცხველს, ბინას და ავეჯს, და შეინახეთ."},{"kind":"NOTES","heading":"ნოტარიუსი და ხელშეკრულების რეგისტრაცია","body":"ხელშეკრულებების უმეტესობას უბრალოდ ორივე მხარე აწერს ხელს. ნოტარიულად დამოწმებული ხელშეკრულება მხოლოდ ზოგ შემთხვევაშია საჭირო, მაგალითად ბინადრობის ნებართვისთვის ან საცხოვრებელი ადგილის რეგისტრაციისთვის. საჯარო რეესტრი იჯარის რეესტრსაც აწარმოებს, თუ გსურთ, რომ თქვენი ხელშეკრულება აღირიცხოს. იუსტიციის სახლში იკითხეთ, რას მოითხოვს ეს თქვენს შემთხვევაში. ხელშეკრულება გქონდეთ თქვენთვის გასაგებ ენაზე ან თარგმანთან ერთად, გვერდიგვერდ."},{"kind":"PROBLEMS","heading":"რა ფუჭდება ყველაზე ხშირად","body":"დეპოზიტს არ აბრუნებენ, რადგან არავის ჩაუწერია, რა მდგომარეობაში იყო ბინა. თქვენს სახელზე ჩნდება ძველი გადასახადი, რომელიც თქვენს მოსვლამდე დაგროვდა. ხელი მესაკუთრემ არ მოაწერა. პირველივე ნახვაზე ხელს ნუ მოაწერთ, გადაიხადეთ საბანკო გადარიცხვით დანიშნულების მითითებით და შეინახეთ ყველა ფოტო და ქვითარი."}]},"ru":{"title":"Аренда жилья","summary":"Аренда в Грузии это в основном договорённость между вами и хозяином. Поэтому всё быстро, но и защищает вас только то, что записано.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Найдите жильё, посмотрите его лично, проверьте, что сдающий действительно собственник, и подпишите письменный договор. Обычно при подписании платят первый месяц и депозит. Для бытовой аренды закон не требует письменного договора, но без него при проблеме вам почти нечего показать, так что делайте его всегда."},{"kind":"WHAT_YOU_NEED","heading":"Что подготовить","body":"Паспорт, плату за первый месяц и депозит. Депозит в один или два месяца это обычная практика при долгой аренде. Это обычай, а не сумма из закона, поэтому впишите в договор, сколько он, когда возвращается и что из него могут удержать. Если квартиру показывает агент, спросите до просмотра, платите ли вы ему что-то."},{"kind":"PRACTICAL","heading":"Проверьте, чья квартира","body":"Национальное агентство публичного реестра (NAPR) ведёт реестр недвижимости, и выписка из него показывает, кому принадлежит объект и есть ли на нём ограничения, ипотека или аренда. Запросить выписку можно на napr.gov.ge или в Доме юстиции. Сравните имя собственника с паспортом того, кто подписывает. Если за собственника подписывает другой человек, попросите доверенность."},{"kind":"PRACTICAL","heading":"Коммунальные платежи","body":"В квартирах свет, газ, воду и интернет обычно оплачивает арендатор отдельно. Договоритесь письменно, кто за что платит. В день въезда сфотографируйте все счётчики, квартиру и мебель и сохраните фото."},{"kind":"NOTES","heading":"Нотариус и регистрация договора","body":"Большинство договоров просто подписывают обе стороны. Нотариальный договор нужен только в некоторых случаях, например для вида на жительство или регистрации места жительства. В публичном реестре также есть реестр аренды, если хотите, чтобы ваш договор был внесён. В Доме юстиции спросите, что для этого нужно в вашем случае. Договор должен быть на понятном вам языке или рядом с переводом."},{"kind":"PROBLEMS","heading":"Что чаще всего идёт не так","body":"Депозит не возвращают, потому что никто не записал, в каком состоянии была квартира. На вас всплывает старый счёт, набежавший до вашего въезда. Подписал не собственник. Не подписывайте в первый же визит, платите банковским переводом с назначением платежа и храните все фото и чеки."}]},"tr":{"title":"Ev kiralamak","summary":"Gürcistan''da kiralama büyük ölçüde sizinle ev sahibi arasındaki bir anlaşmadır. Bu işi hızlandırır, ama korumanızın yazıya döktüğünüz kadar olduğu anlamına da gelir.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Bir yer bulun, kendiniz gidip görün, size kiralayan kişinin gerçekten sahibi olduğunu kontrol edin ve yazılı bir sözleşme imzalayın. İmzada genellikle ilk ayın kirası ve depozito ödenir. Konut kiralamasında kanun yazılı sözleşme şart koşmaz, ama sözleşme olmadan bir sorun çıktığında gösterecek pek bir şeyiniz olmaz, bu yüzden her zaman yapın."},{"kind":"WHAT_YOU_NEED","heading":"Hazır olması gerekenler","body":"Pasaportunuz, ilk ayın kirası ve depozito. Uzun kiralamalarda bir ya da iki aylık depozito yaygın bir uygulamadır. Bu bir alışkanlıktır, kanunda belirlenmiş bir tutar değildir. Sözleşmede ne kadar olduğunu, ne zaman iade edileceğini ve neyin kesilebileceğini yazın. Daireyi bir emlakçı gösteriyorsa, görmeden önce ona bir ücret ödeyip ödemeyeceğinizi sorun."},{"kind":"PRACTICAL","heading":"Dairenin kime ait olduğunu kontrol edin","body":"Kamu Sicili Ulusal Ajansı (NAPR) gayrimenkul sicilini tutar. Sicil özeti mülkün kime ait olduğunu ve üzerinde kısıtlama, ipotek ya da kira kaydı olup olmadığını gösterir. napr.gov.ge üzerinden ya da bir Kamu Hizmetleri Salonu''ndan isteyebilirsiniz. Malikin adını imzalayan kişinin pasaportuyla karşılaştırın. Malik yerine başkası imzalıyorsa vekâletnamesini görmek isteyin."},{"kind":"PRACTICAL","heading":"Faturalar","body":"Dairelerde elektrik, gaz, su ve interneti genellikle kiracı ayrıca öder. Kimin neyi ödediğini yazılı olarak kararlaştırın. Taşındığınız gün tüm sayaçların, dairenin ve eşyaların fotoğrafını çekin ve saklayın."},{"kind":"NOTES","heading":"Noter ve sözleşmenin tescili","body":"Sözleşmelerin çoğunu iki taraf imzalar, o kadar. Noter onaylı sözleşme yalnızca bazı durumlarda gerekir, örneğin oturma izni başvurusu ya da ikamet adresi kaydı için. Kamu Sicili, sözleşmenizin kayda geçmesini isterseniz bir kira sicili de tutar. Sizin durumunuzda bunun ne gerektirdiğini Kamu Hizmetleri Salonu''nda sorun. Sözleşme anladığınız bir dilde ya da yanında çevirisiyle olsun."},{"kind":"PROBLEMS","heading":"En sık ne ters gider","body":"Depozito iade edilmez, çünkü kimse dairenin durumunu yazmamıştır. Siz gelmeden önceki eski bir fatura sizin adınıza çıkar. İmzalayan kişi malik değildir. İlk ziyarette imzalamayın, açıklamalı banka havalesiyle ödeyin ve tüm fotoğrafları ve makbuzları saklayın."}]},"ar":{"title":"استئجار بيت","summary":"الإيجار في جورجيا في الغالب اتفاق بينك وبين المالك. هذا يجعل الأمر سريعًا، لكنه يعني أيضًا أن حمايتك هي ما تكتبه على الورق.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"ابحث عن مكان، وعاينه بنفسك، وتأكد أن من يؤجرك هو المالك فعلًا، ووقّع عقد إيجار مكتوبًا. عادة تدفع إيجار الشهر الأول والتأمين عند التوقيع. القانون لا يشترط عقدًا مكتوبًا لإيجار السكن، لكن بدونه لن يكون لديك ما تثبت به حقك إذا حصلت مشكلة، فاحرص عليه دائمًا."},{"kind":"WHAT_YOU_NEED","heading":"ما تجهّزه","body":"جوازك، وإيجار الشهر الأول، والتأمين. التأمين بقيمة شهر أو شهرين عادة شائعة في الإيجار الطويل. هو عُرف وليس مبلغًا يحدده القانون، فاكتب في العقد كم هو، ومتى يُعاد إليك، وما الذي يمكن خصمه منه. وإذا عرض عليك وسيط الشقة، فاسأله قبل المعاينة هل ستدفع له شيئًا."},{"kind":"PRACTICAL","heading":"تحقق من مالك الشقة","body":"الوكالة الوطنية للسجل العام (NAPR) تمسك سجل العقارات، ومستخرج السجل يبيّن مالك العقار وما إذا كانت عليه قيود أو رهن أو عقود إيجار. يمكنك طلبه من napr.gov.ge أو من أي قاعة للخدمات العامة. قارن اسم المالك بجواز الشخص الذي يوقّع، وإذا وقّع شخص آخر بدل المالك فاطلب رؤية توكيله."},{"kind":"PRACTICAL","heading":"الفواتير والخدمات","body":"في الشقق يدفع المستأجر عادة الكهرباء والغاز والماء والإنترنت بشكل منفصل. اتفقوا كتابةً على من يدفع ماذا. ويوم دخولك صوّر كل العدادات والشقة والأثاث واحتفظ بالصور."},{"kind":"NOTES","heading":"كاتب العدل وتسجيل العقد","body":"معظم العقود يوقّعها الطرفان وحسب. العقد الموثّق عند كاتب العدل مطلوب في حالات معينة فقط، مثل طلب الإقامة أو تسجيل مكان السكن. والسجل العام يمسك أيضًا سجلًا لعقود الإيجار إذا أردت تسجيل عقدك. اسأل في قاعة الخدمات العامة عما يتطلبه ذلك في حالتك. واجعل العقد بلغة تفهمها، أو مع ترجمته جنبًا إلى جنب."},{"kind":"PROBLEMS","heading":"ما الذي يحدث عادة","body":"لا يُعاد التأمين لأن أحدًا لم يدوّن حالة الشقة. تظهر باسمك فاتورة قديمة من قبل وصولك. الشخص الذي وقّع لم يكن المالك. لا توقّع في الزيارة الأولى، وادفع بتحويل بنكي مع ملاحظة، واحتفظ بكل صورة وإيصال."}]},"he":{"title":"לשכור דירה","summary":"שכירות בגאורגיה היא בעיקר הסכם בינכם לבין בעל הדירה. זה הופך את התהליך למהיר, אבל זה גם אומר שההגנה שלכם היא מה שכתוב על הנייר.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"מצאו דירה, ראו אותה בעצמכם, בדקו שמי שמשכיר לכם באמת הבעלים, וחתמו על חוזה בכתב. בדרך כלל משלמים בחתימה את החודש הראשון ופיקדון. החוק לא דורש חוזה כתוב לשכירות למגורים, אבל בלי חוזה אין לכם כמעט מה להראות אם משהו משתבש, אז תמיד תעשו אחד."},{"kind":"WHAT_YOU_NEED","heading":"מה להכין","body":"דרכון, שכר דירה לחודש הראשון ופיקדון. פיקדון של חודש או חודשיים נהוג בשכירות ארוכה. זה מנהג ולא סכום שנקבע בחוק, אז כתבו בחוזה כמה הוא, מתי מקבלים אותו בחזרה ומה מותר לקזז ממנו. אם מתווך מראה לכם את הדירה, שאלו לפני הביקור אם אתם משלמים לו משהו."},{"kind":"PRACTICAL","heading":"בדקו של מי הדירה","body":"הסוכנות הלאומית לרישום ציבורי (NAPR) מנהלת את מרשם המקרקעין, ונסח מהמרשם מראה מי הבעלים של הנכס והאם יש עליו הגבלות, משכנתאות או שכירויות. אפשר לבקש נסח ב־napr.gov.ge או באולם שירותים ציבוריים. השוו את שם הבעלים לדרכון של מי שחותם. אם מישהו אחר חותם בשם הבעלים, בקשו לראות ייפוי כוח."},{"kind":"PRACTICAL","heading":"חשבונות","body":"בדירות, חשמל, גז, מים ואינטרנט משולמים בדרך כלל בנפרד על ידי השוכר. סכמו בכתב מי משלם מה. ביום הכניסה צלמו כל מונה, את הדירה ואת הרהיטים, ושמרו את התמונות."},{"kind":"NOTES","heading":"נוטריון ורישום החוזה","body":"את רוב החוזים פשוט חותמים שני הצדדים. חוזה נוטריוני נדרש רק במקרים מסוימים, למשל לבקשת אשרת שהייה או לרישום מקום מגורים. במרשם הציבורי יש גם מרשם שכירויות, אם רוצים שהחוזה יירשם. שאלו באולם שירותים ציבוריים מה זה דורש במקרה שלכם. דאגו שהחוזה יהיה בשפה שאתם מבינים, או לצד תרגום."},{"kind":"PROBLEMS","heading":"מה בדרך כלל משתבש","body":"הפיקדון לא מוחזר, כי אף אחד לא רשם באיזה מצב הייתה הדירה. חשבון ישן מלפני שהגעתם מופיע על שמכם. מי שחתם לא היה הבעלים. אל תחתמו בביקור הראשון, שלמו בהעברה בנקאית עם הערה, ושמרו כל תמונה וקבלה."}]}}'::jsonb,
        'PROCESS', 'PRACTICAL_CONTEXT', 80,
        true, false, null,
        now(), now() + interval '90 days')
