insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'written-lease-not-required', 'LEGAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"A written rental agreement is not legally required for household rentals, but it is advisable. Notarisation is needed only in certain situations, such as a residence permit application or registering a place of residence.","ka":"საყოფაცხოვრებო ქირაობისთვის წერილობითი ხელშეკრულება კანონით სავალდებულო არ არის, მაგრამ სასურველია. ნოტარიული დამოწმება მხოლოდ ზოგ შემთხვევაშია საჭირო, მაგალითად ბინადრობის ნებართვისთვის ან საცხოვრებელი ადგილის რეგისტრაციისთვის.","ru":"Для бытовой аренды письменный договор по закону не обязателен, но желателен. Нотариальное заверение нужно только в некоторых случаях, например для вида на жительство или регистрации места жительства.","tr":"Konut kiralamasında yazılı sözleşme kanunen zorunlu değildir, ama tavsiye edilir. Noter onayı yalnızca bazı durumlarda gerekir, örneğin oturma izni başvurusu ya da ikamet adresi kaydı.","ar":"لا يشترط القانون عقدًا مكتوبًا لإيجار السكن، لكنه مستحسن. والتوثيق عند كاتب العدل مطلوب في حالات معينة فقط، مثل طلب الإقامة أو تسجيل مكان السكن.","he":"לשכירות למגורים החוק לא מחייב חוזה כתוב, אבל מומלץ לעשות אותו. אישור נוטריוני נדרש רק במקרים מסוימים, למשל לבקשת אשרת שהייה או לרישום מקום מגורים."}'::jsonb, null, null,
       false
from public.expat_topics where slug = 'renting-a-home'
