insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'renting-a-home'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Madloba.info' and url is not distinct from 'https://madloba.info/en/blog/laws-of-georgia/legal-subtleties-of-renting-in-georgia/'
  order by created_at limit 1) c
where f.fact_key = 'written-lease-not-required'
on conflict do nothing;
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'deposit-common-practice', 'MARKET', 'COMMUNITY_EXPERIENCE', 'ESTABLISHED',
       '{"en":"For long rentals a contract is often asked for, with a deposit of one to two months, and utilities are usually paid separately. This is common practice, not a rule in law.","ka":"გრძელვადიან ქირაობაზე ხშირად ითხოვენ ხელშეკრულებას ერთი ან ორი თვის დეპოზიტით, კომუნალურს კი, როგორც წესი, ცალკე იხდიან. ეს გავრცელებული პრაქტიკაა და არა კანონის მოთხოვნა.","ru":"При долгой аренде часто просят договор и депозит в один или два месяца, а коммунальные услуги обычно оплачиваются отдельно. Это обычная практика, а не норма закона.","tr":"Uzun kiralamalarda genellikle sözleşme ve bir ya da iki aylık depozito istenir, faturalar çoğunlukla ayrıca ödenir. Bu yaygın bir uygulamadır, kanuni bir kural değildir.","ar":"في الإيجار الطويل يُطلب غالبًا عقد مع تأمين بقيمة شهر أو شهرين، وتُدفع الخدمات عادة بشكل منفصل. هذه عادة شائعة وليست قاعدة في القانون.","he":"בשכירות ארוכה מבקשים לרוב חוזה ופיקדון של חודש עד חודשיים, והחשבונות משולמים בדרך כלל בנפרד. זה נוהג מקובל, לא כלל בחוק."}'::jsonb, '{"depositMonthsLow":1,"depositMonthsHigh":2}'::jsonb, null,
       false
